\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\newtheorem{conjecture}[theorem]{Conjecture}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\DeclareMathOperator{\unionMS}{unionMS}
\DeclareMathOperator{\RReachable}{RReachable}
\newcommand{\rest}{\mathrm{rest}}
\newcommand{\val}{\mathrm{val}}
\newcommand{\cons}{::_m}
\title{A Compositional Theory of Quadratic Basis Exchange, \\ with a Complete Solution in Rank One}
\author{Aristotle}
\date{July 14, 2026}
\begin{document}
\begin{abstract}
White's Quadratic Exchange Conjecture (Part 3) asserts that in any matroid, any two multisets of bases sharing the same multiset union of ground-set elements are related by a finite sequence of quadratic exchange moves that replace two bases by two others while conserving the combined element multiset. The conjecture is open in general; its stronger symmetric variant is false. We prove basis-preserving reachability is a congruence for multiset addition, isolate the atomic two-basis move as a reusable theorem over any basis family, and prove Part 3 unconditionally for all rank-one uniform matroids $U_{1,n}$, where the multiset union determines the configuration. We include a single-basis rigidity classification and a reduction of the general uniform case to an extraction lemma.
\end{abstract}
\maketitle
\section{Introduction}
Matroids axiomatize independence common to linear algebra and graph theory; bases enjoy rich exchange behavior. White's conjectures elevate exchange from single bases to collections of bases. The strongest (symmetric exchange) variant is known false. Part 3 permits any element-conserving replacement of two bases by two others; it is open in general. We contribute a structural toolkit and resolve the rank-one uniform family. The philosophy is that reachability is local and compositional; the conjecture then reduces to a bookkeeping induction whose only missing ingredient is an extraction lemma, and whose base case (rank one) we prove outright.
\section{Definitions}
Throughout $\alpha$ has decidable equality; bases are finite subsets of $\alpha$, and $B \mapsto B.\val$ is injective.
\begin{definition}[Basis family] A basis family is a predicate $\mathcal{B}$ selecting which finite sets count as bases. \end{definition}
\begin{definition}[Uniform basis] The rank-$r$ uniform family holds of $B$ iff $|B|=r$; on $\{0,\dots,n-1\}$ this is $U_{r,n}$. \end{definition}
\begin{definition}[Configuration] A configuration is a multiset of bases; $C+E$ places two together, $B \cons C$ conses one basis. \end{definition}
\begin{definition}[Fingerprint] $\unionMS(C)=\sum_{B\in C} B.\val$, with multiplicity. For a singleton, $\unionMS(\{B\})=B.\val$. \end{definition}
\begin{definition}[Quadratic move] A move from $C$ to $D$ exists when $C=B_1\cons B_2\cons\rest$, $D=C_1\cons C_2\cons\rest$, $B_1.\val+B_2.\val=C_1.\val+C_2.\val$, and $\mathcal{B}\,C_1$, $\mathcal{B}\,C_2$. \end{definition}
\begin{definition}[Reachability] The equivalence relation generated by the single-move relation. \end{definition}
Moves preserve the fingerprint, so equal-union is necessary for reachability; Part 3 conjectures it sufficient.
\section{Congruence of reachability}
\begin{lemma}[Moves are local]\label{lem:local} If $C$ moves to $D$, then $C+E$ moves to $D+E$. \end{lemma}
\begin{proof}[Proof sketch] Reassociate cons with addition: both are the same move with remainder $\rest+E$. \end{proof}
\begin{theorem}[Right congruence]\label{thm:right} If $C$ reaches $D$ then $C+E$ reaches $D+E$. \end{theorem}
\begin{proof}[Proof sketch] Induct on the closure using Lemma~\ref{lem:local}. \end{proof}
\begin{theorem}[Left congruence]\label{thm:left} If $C$ reaches $D$ then $E+C$ reaches $E+D$. \end{theorem}
\begin{proof}[Proof sketch] Commutativity reduces to Theorem~\ref{thm:right}. \end{proof}
\begin{theorem}[Full congruence] If $C$ reaches $D$ and $C'$ reaches $D'$ then $C+C'$ reaches $D+D'$. \end{theorem}
\begin{proof}[Proof sketch] Chain Theorems~\ref{thm:right} and \ref{thm:left} by transitivity. \end{proof}
\begin{corollary}[Cons congruence]\label{cor:cons} If $C$ reaches $D$ then $B\cons C$ reaches $B\cons D$. \end{corollary}
\begin{proof}[Proof sketch] Consing $B$ is left-addition of $\{B\}$; apply Theorem~\ref{thm:left}. \end{proof}
\section{Two-basis reconfiguration}
\begin{theorem}[Two-basis reconfiguration]\label{thm:two} For any family $\mathcal{B}$, ambient $\rest$, and bases with $B_1.\val+B_2.\val=C_1.\val+C_2.\val$, $\mathcal{B}\,C_1$, $\mathcal{B}\,C_2$: $B_1\cons B_2\cons\rest$ reaches $C_1\cons C_2\cons\rest$. \end{theorem}
\begin{proof}[Proof sketch] The data exhibit a single move. \end{proof}
\begin{theorem}[Uniform connectivity]\label{thm:unitwo} In $U_{r,n}$, any $r$-subsets $C_1,C_2$ conserving elements are reachable from $B_1,B_2$ in one move. \end{theorem}
\begin{proof}[Proof sketch] Specialize Theorem~\ref{thm:two} with $\rest=0$; membership is $|C_1|=|C_2|=r$. \end{proof}
\section{Rank-one uniform matroids}
\begin{lemma}[Single-basis rigidity]\label{lem:single} If $\unionMS(\{B\})=\unionMS(\{C\})$ then $B=C$. \end{lemma}
\begin{proof}[Proof sketch] Injectivity of $B\mapsto B.\val$. \end{proof}
\begin{lemma}[Reconstruction]\label{lem:recon} If every basis in $C$ is a singleton, $C=\unionMS(C).\mathrm{map}\,(a\mapsto\{a\})$. \end{lemma}
\begin{proof}[Proof sketch] Multiset induction; mapping inverts the passage from singletons to elements. \end{proof}
\begin{theorem}[Part 3 in rank one]\label{thm:rank1} For $U_{1,n}$, equal-union configurations are reachable. \end{theorem}
\begin{proof}[Proof sketch] By Lemma~\ref{lem:recon} equal fingerprints force $C=D$; conclude by reflexivity. \end{proof}
The result is unconditional for all $n$: at rank one a move cannot rearrange content, and the conjecture's content reappears at rank $\geq 2$.
\section{The general uniform case}
\begin{conjecture}[Extraction]\label{conj:extract} If $C$ is non-empty of $r$-subsets and $T$ is an $r$-subset with $T.\val\leq\unionMS(C)$, there is $C'$ with $C$ reaching $T\cons C'$, $C'$ uniform, $|C'|=|C|-1$. \end{conjecture}
\begin{theorem}[Reduction]\label{thm:reduce} Extraction implies Part 3 for $U_{r,n}$ of all ranks. \end{theorem}
\begin{proof}[Proof sketch] Induct on $|C|=|D|$: peel $T$ off $D$, extract to the head of $C$, drop the common $T$ via Corollary~\ref{cor:cons}, recurse. \end{proof}
The atomic step is Theorem~\ref{thm:unitwo}; the remaining work is well-founded bookkeeping.
\section{Applications and discussion}
White's conjectures originate in bracket algebras; reachability under local moves is central to combinatorial reconfiguration, and connectivity of the move graph enables Markov-chain sampling of configurations with a prescribed fingerprint. The congruence theory converts global connectivity into a local induction; the symmetric variant's failure shows Part 3's repacking freedom is essential.
\section{Future work}
Prove the extraction lemma to obtain Part 3 for all uniform matroids; port the template to strongly base-orderable matroids via a compatible base ordering.
\end{document}

