from typing import FrozenSet, Iterator, Tuple

Basis = FrozenSet[int]

def uniform_repackings(b1: Basis, b2: Basis, r: int) -> Iterator[Tuple[Basis, Basis]]:
    pooled: Counter = Counter()
    for e in b1:
        pooled[e] += 1
