import itertools
import networkx as nx
import matplotlib.pyplot as plt
from collections import Counter

def fingerprint(cfg):
    total = Counter()
    for b in cfg:
        for e in b:
            total[e] += 1
    return tuple(sorted(total.items()))

def repackings(b1, b2, r=2):
    pooled = Counter(b1) + Counter(b2)
    out = []
    for c1 in itertools.combinations(sorted(pooled), r):
        rem = pooled.copy()
        ok = all((rem.__setitem__(e, rem[e] - 1) or rem[e] >= 0) for e in c1)
        c2 = sorted(rem.elements())
        if ok and len(c2) == r and len(set(c2)) == r:
            out.append((frozenset(c1), frozenset(c2)))
    return out

def canon(cfg):
    return tuple(sorted(tuple(sorted(b)) for b in cfg))

elems = [1, 2, 3, 4]
all_bases = [frozenset(c) for c in itertools.combinations(elems, 2)]
verts = set()
for pair in itertools.combinations_with_replacement(all_bases, 2):
    if fingerprint(pair) == fingerprint((frozenset({1,2}), frozenset({3,4}))):
        verts.add(canon(pair))
G = nx.Graph()
G.add_nodes_from(verts)
for v in verts:
    cfg = [frozenset(b) for b in v]
    for c1, c2 in repackings(cfg[0], cfg[1]):
        nb = canon((c1, c2))
        if nb in verts and nb != v:
            G.add_edge(v, nb)
pos = nx.spring_layout(G, seed=1)
nx.draw(G, pos, with_labels=True, node_color='#8ecae6', node_size=1600, font_size=8)
plt.title('Quadratic-exchange reconfiguration graph (fixed fingerprint)')
