import itertools, random
from collections import Counter
import matplotlib.pyplot as plt

def fingerprint(cfg):
    t = Counter()
    for b in cfg:
        for e in b:
            t[e] += 1
    return tuple(sorted(t.items()))

def canon(cfg):
    return tuple(sorted(tuple(sorted(b)) for b in cfg))

def repackings(b1, b2, r=2):
    pooled = Counter(b1) + Counter(b2)
    out = []
    for c1 in itertools.combinations(sorted(pooled), r):
        rem = pooled.copy(); ok = True
        for e in c1:
            rem[e] -= 1
            if rem[e] < 0: ok = False; break
        c2 = sorted(rem.elements())
        if ok and len(c2) == r and len(set(c2)) == r:
            out.append((frozenset(c1), frozenset(c2)))
    return out

def neighbors(cfg):
    lst = list(cfg); res = []
    for i, j in itertools.combinations(range(len(lst)), 2):
        for c1, c2 in repackings(lst[i], lst[j]):
            nc = lst[:i] + lst[i+1:j] + lst[j+1:] + [c1, c2]
            res.append(tuple(nc))
    return res

def bfs_len(start, goal):
    from collections import deque
    if fingerprint(start) != fingerprint(goal): return None
    sk, gk = canon(start), canon(goal); seen = {sk}; q = deque([(start, 0)])
    while q:
        cur, d = q.popleft()
        if canon(cur) == gk: return d
        for nb in neighbors(cur):
            k = canon(nb)
            if k not in seen:
                seen.add(k); q.append((nb, d + 1))
    return None

random.seed(0)
elems = list(range(1, 7))
lengths = []
for _ in range(200):
    base_fp = [frozenset(random.sample(elems, 2)) for _ in range(3)]
    perm = base_fp[:]; random.shuffle(perm)
    d = bfs_len(tuple(base_fp), tuple(perm))
    if d is not None:
        lengths.append(d)
plt.hist(lengths, bins=range(0, max(lengths) + 2), color='#fb8500', edgecolor='k')
plt.xlabel('quadratic moves to reconfigure'); plt.ylabel('frequency')
plt.title('Reconfiguration path lengths (rank-2, 3 bases)')
plt.tight_layout(); plt.savefig('path_lengths.png', dpi=140)
print('samples:', len(lengths), 'max length:', max(lengths))

